local({
  hours <- recode_values(as.numeric(tv_dau), 0 ~ 0, 1 ~ 0.25, 2 ~ 0.75, 3 ~ 1.25, 4 ~ 1.75, 5 ~ 2)
  days <- coalesce(
    recode_values(as.numeric(tv_oft_5pt), 0 ~ 0, 1 ~ 0.5, 2 ~ 2.5, 3 ~ 3.5, 4 ~ 7),
    recode_values(as.numeric(tv_oft_6pt), 0 ~ 0, 1 ~ 0.5, 2 ~ 1, 3 ~ 2.5, 4 ~ 3.5, 5 ~ 7)
  )
  case_when(days == 0 | hours == 0 ~ 0, .default = hours * days / 7)
})

