local({
  items <- cbind(as.numeric(aq08p), as.numeric(aq09p), as.numeric(aq10p))
  case_when(rowSums(items >= 1, na.rm = TRUE) > 0 ~ "TRUE", rowSums(!is.na(items)) > 0 ~ "FALSE")
})
